    data = <<data::binary, scratch::little-size(flush)-unit(8)>>
    scratch = scratch >>> (flush <<< 3)
    scratch_bits = scratch_bits &&& 7
    v = value.b48 &&& 0xFFFFFFFF
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 32
    flush = scratch_bits >>> 3
    data = <<data::binary, scratch::little-size(flush)-unit(8)>>
    scratch = scratch >>> (flush <<< 3)
    scratch_bits = scratch_bits &&& 7
    v = value.b48 >>> 32 &&& 0xFFFF
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 16
    flush = scratch_bits >>> 3
    data = <<data::binary, scratch::little-size(flush)-unit(8)>>
    scratch = scratch >>> (flush <<< 3)
    scratch_bits = scratch_bits &&& 7
    if scratch_bits != 0, do: <<data::binary, scratch>>, else: data
  end

  # read_bench_bits decodes the first num_bits of data — the family read verdict:
  # :error rejects the wire (bounds, ranges, wire constants, padding);
  # hostile bytes never raise. No slack past the payload is required.
  def read_bench_bits(data, num_bits) when is_binary(data) and is_integer(num_bits) do
    try do
      if num_bits > byte_size(data) * 8 do
        # the payload cannot exceed the buffer behind it
        throw(:invalid)
      end

      bits_read = 0
      if bits_read + 156 > num_bits, do: throw(:invalid)
      v = rd(data, bits_read, 7)
      bits_read = bits_read + 7
      v_b7 = v
      v = rd(data, bits_read, 13)
      bits_read = bits_read + 13
      v_b13 = v
      v = rd(data, bits_read, 23)
      bits_read = bits_read + 23
      v_b23 = v
      v = rd(data, bits_read, 3)
      bits_read = bits_read + 3
      v_b3 = v
      v = rd(data, bits_read, 32)
      bits_read = bits_read + 32
      v_b32 = v
      v = rd(data, bits_read, 11)
      bits_read = bits_read + 11
      v_b11 = v
      v = rd(data, bits_read, 19)
      bits_read = bits_read + 19
      v_b19 = v
      v = rd(data, bits_read, 32)
      bits_read = bits_read + 32
      w = v
      v = rd(data, bits_read, 16)
      bits_read = bits_read + 16
      w = w ||| v <<< 32
      v_b48 = w
      # the final position is unobserved — the verdict and value are the surface
      _ = bits_read

      value = %Bench.BenchBits{
        b7: v_b7,
        b13: v_b13,
        b23: v_b23,
        b3: v_b3,
        b32: v_b32,
        b11: v_b11,
        b19: v_b19,
        b48: v_b48
      }

      {:ok, value}
    catch
      :invalid -> :error
    end
  end

  # measure_bench_bits is the exact wire bits write_bench_bits would produce for value —
  # trusted like the writer; static runs fold to literals at generation time.
  def measure_bench_bits(_value), do: 156

  # bench_mixed_max_bits is the longest wire path; align pads at worst case (SPEC §6.1).
  # bench_mixed_max_bytes is rounded up to the family 8-byte write-buffer granularity.
  def bench_mixed_max_bits, do: 168
  def bench_mixed_max_bytes, do: 24

  # The §5 zero form: all-zero storage; specified defaults live only in
  # construction (%Bench.BenchMixed{}).
  def zero_bench_mixed do
    %Bench.BenchMixed{
      sequence: 0,
      ack_bits: 0,
      entity_id: 0,
      pos_x: 0,
      pos_y: 0,
      pos_z: 0,
      yaw: 0,
      moving: false,
      firing: false,
      timestamp: 0,
      weapon: 0
    }
  end

  # write_bench_mixed packs value into a fresh binary — the trusted writer; the O(1)
  # contract checks raise ArgumentError, always on (the BEAM has no
  # compile-out assert). Returns the wire bytes.
  def write_bench_mixed(value) do
    data = <<>>
    scratch = 0
    scratch_bits = 0

    if value.sequence < 0 do
      raise ArgumentError, "value.sequence is below the wire minimum"
    end

    if value.sequence > 65535 do
      raise ArgumentError, "value.sequence is above the wire maximum"
    end

    v = value.sequence
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 16
    flush = scratch_bits >>> 3
    data = <<data::binary, scratch::little-size(flush)-unit(8)>>
    scratch = scratch >>> (flush <<< 3)
    scratch_bits = scratch_bits &&& 7
    v = value.ack_bits &&& 0xFFFFFFFF
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 32
    flush = scratch_bits >>> 3
    data = <<data::binary, scratch::little-size(flush)-unit(8)>>
    scratch = scratch >>> (flush <<< 3)
    scratch_bits = scratch_bits &&& 7
    v = value.entity_id &&& 0xFFF
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 12
    flush = scratch_bits >>> 3
    data = <<data::binary, scratch::little-size(flush)-unit(8)>>
    scratch = scratch >>> (flush <<< 3)
    scratch_bits = scratch_bits &&& 7

    if value.pos_x < -16384 do
      raise ArgumentError, "value.pos_x is below the wire minimum"
    end

    if value.pos_x > 16383 do
      raise ArgumentError, "value.pos_x is above the wire maximum"
    end

    v = value.pos_x + 16384
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 15
    flush = scratch_bits >>> 3
    data = <<data::binary, scratch::little-size(flush)-unit(8)>>
    scratch = scratch >>> (flush <<< 3)
    scratch_bits = scratch_bits &&& 7

    if value.pos_y < -16384 do
      raise ArgumentError, "value.pos_y is below the wire minimum"
    end

    if value.pos_y > 16383 do
      raise ArgumentError, "value.pos_y is above the wire maximum"
    end

    v = value.pos_y + 16384
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 15
    flush = scratch_bits >>> 3
    data = <<data::binary, scratch::little-size(flush)-unit(8)>>
    scratch = scratch >>> (flush <<< 3)
    scratch_bits = scratch_bits &&& 7

    if value.pos_z < -16384 do
      raise ArgumentError, "value.pos_z is below the wire minimum"
    end

    if value.pos_z > 16383 do
      raise ArgumentError, "value.pos_z is above the wire maximum"
    end

    v = value.pos_z + 16384
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 15
    flush = scratch_bits >>> 3
    data = <<data::binary, scratch::little-size(flush)-unit(8)>>
    scratch = scratch >>> (flush <<< 3)
    scratch_bits = scratch_bits &&& 7
    v = value.yaw &&& 0x1FF
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 9
    flush = scratch_bits >>> 3
    data = <<data::binary, scratch::little-size(flush)-unit(8)>>
    scratch = scratch >>> (flush <<< 3)
    scratch_bits = scratch_bits &&& 7
    v = if value.moving, do: 1, else: 0
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 1
    flush = scratch_bits >>> 3
    data = <<data::binary, scratch::little-size(flush)-unit(8)>>
    scratch = scratch >>> (flush <<< 3)
    scratch_bits = scratch_bits &&& 7
    v = if value.firing, do: 1, else: 0
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 1
    flush = scratch_bits >>> 3
    data = <<data::binary, scratch::little-size(flush)-unit(8)>>
    scratch = scratch >>> (flush <<< 3)
    scratch_bits = scratch_bits &&& 7
    v = value.timestamp &&& 0xFFFFFFFF
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 32
    flush = scratch_bits >>> 3
    data = <<data::binary, scratch::little-size(flush)-unit(8)>>
    scratch = scratch >>> (flush <<< 3)
    scratch_bits = scratch_bits &&& 7
    v = value.timestamp >>> 32 &&& 0xFFFF
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 16
    flush = scratch_bits >>> 3
    data = <<data::binary, scratch::little-size(flush)-unit(8)>>
    scratch = scratch >>> (flush <<< 3)
    scratch_bits = scratch_bits &&& 7

    if value.weapon < 0 do
      raise ArgumentError, "value.weapon is below the wire minimum"
    end

    if value.weapon > 15 do
      raise ArgumentError, "value.weapon is above the wire maximum"
    end

    v = value.weapon
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 4
    flush = scratch_bits >>> 3
    data = <<data::binary, scratch::little-size(flush)-unit(8)>>
    scratch = scratch >>> (flush <<< 3)
    scratch_bits = scratch_bits &&& 7
    if scratch_bits != 0, do: <<data::binary, scratch>>, else: data
  end

  # read_bench_mixed decodes the first num_bits of data — the family read verdict:
  # :error rejects the wire (bounds, ranges, wire constants, padding);
  # hostile bytes never raise. No slack past the payload is required.
  def read_bench_mixed(data, num_bits) when is_binary(data) and is_integer(num_bits) do
    try do
      if num_bits > byte_size(data) * 8 do
        # the payload cannot exceed the buffer behind it
        throw(:invalid)
      end

      bits_read = 0
      if bits_read + 168 > num_bits, do: throw(:invalid)
      v = rd(data, bits_read, 16)
      bits_read = bits_read + 16
      v_sequence = v
      v = rd(data, bits_read, 32)
      bits_read = bits_read + 32
      v_ack_bits = v
      v = rd(data, bits_read, 12)
      bits_read = bits_read + 12
      v_entity_id = v
      v = rd(data, bits_read, 15)
      bits_read = bits_read + 15
      v_pos_x = v - 16384
      v = rd(data, bits_read, 15)
      bits_read = bits_read + 15
      v_pos_y = v - 16384
      v = rd(data, bits_read, 15)
      bits_read = bits_read + 15
      v_pos_z = v - 16384
      v = rd(data, bits_read, 9)
      bits_read = bits_read + 9
      v_yaw = v
      v = rd(data, bits_read, 1)
      bits_read = bits_read + 1
      v_moving = v == 1
      v = rd(data, bits_read, 1)
      bits_read = bits_read + 1
      v_firing = v == 1
      v = rd(data, bits_read, 32)
      bits_read = bits_read + 32
      w = v
      v = rd(data, bits_read, 16)
      bits_read = bits_read + 16
      w = w ||| v <<< 32
      v_timestamp = w
      v = rd(data, bits_read, 4)
      bits_read = bits_read + 4
      v_weapon = v
      # the final position is unobserved — the verdict and value are the surface
      _ = bits_read

      value = %Bench.BenchMixed{
        sequence: v_sequence,
        ack_bits: v_ack_bits,
        entity_id: v_entity_id,
        pos_x: v_pos_x,
        pos_y: v_pos_y,
        pos_z: v_pos_z,
        yaw: v_yaw,
        moving: v_moving,
        firing: v_firing,
        timestamp: v_timestamp,
        weapon: v_weapon
      }

      {:ok, value}
    catch
      :invalid -> :error
    end
  end

  # measure_bench_mixed is the exact wire bits write_bench_mixed would produce for value —
  # trusted like the writer; static runs fold to literals at generation time.
  def measure_bench_mixed(_value), do: 168

  defp w_bench_packet_blob([], data, scratch, scratch_bits), do: {data, scratch, scratch_bits}

  defp w_bench_packet_blob([e | rest], data, scratch, scratch_bits) do
    v = e &&& 0xFF
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 8
    flush = scratch_bits >>> 3
    data = <<data::binary, scratch::little-size(flush)-unit(8)>>
    scratch = scratch >>> (flush <<< 3)
    scratch_bits = scratch_bits &&& 7
    w_bench_packet_blob(rest, data, scratch, scratch_bits)
  end

  defp r_bench_packet_blob(0, acc, _data, _num_bits, bits_read),
    do: {bits_read, Enum.reverse(acc)}

  defp r_bench_packet_blob(remaining, acc, data, num_bits, bits_read) do
    v = rd(data, bits_read, 8)
    bits_read = bits_read + 8
    e = v
    r_bench_packet_blob(remaining - 1, [e | acc], data, num_bits, bits_read)
  end

  # The port's 40-bit window decode (issue #167): enough for a 7-bit offset
  # plus a 32-bit group, small enough that no intermediate ever boxes. The
  # callers have already priced the read inside num_bits, so the tail
  # fallback decodes exactly the bytes that exist.
  defp rd(data, bits_read, bits) do
    i = bits_read >>> 3

    window =
      case data do
        <<_::binary-size(^i), w::little-40, _::binary>> -> w
        <<_::binary-size(^i), rest::binary>> -> :binary.decode_unsigned(rest, :little)
      end

    window >>> (bits_read &&& 7) &&& (1 <<< bits) - 1
  end

  # The 32-bit IEEE-754 pattern of a float value for the write path — a
  # non-finite pattern travels as {:nonfinite, bits}, since no BEAM float
  # term can hold it (the serialize.elixir convention). Caller errors raise;
  # the checks are O(1).
  defp f32_bits(value) when is_float(value) do
    <<bits::little-32>> = <<value::float-32-little>>

    if (bits >>> 23 &&& 0xFF) == 0xFF do
      raise ArgumentError, "float overflows float32; write {:nonfinite, bits} instead"
    end

    bits
  end

  defp f32_bits({:nonfinite, bits}) when bits >= 0 and bits <= 0xFFFFFFFF do
    if (bits >>> 23 &&& 0xFF) != 0xFF do
      raise ArgumentError, "{:nonfinite, bits} carries a finite float32 pattern; write the float"
    end

    bits
  end

  # The value of a 32-bit pattern for the read path: the float for a finite
  # pattern, {:nonfinite, bits} otherwise. Never raises — the bits are
  # untrusted.
  defp f32_value(bits) do
    if (bits >>> 23 &&& 0xFF) != 0xFF do
      <<value::float-32-little>> = <<bits::little-32>>
      value
    else
      {:nonfinite, bits}
    end
  end
end
